"Называть ударные инструменты и делить их на группы, узнавать музыку Эдварда Грига о природе.": "Schlaginstrumente benennen und in Gruppen einteilen, die Musik von Edvard Grieg über die Natur erkennen.",
"Природные явления": "Naturerscheinungen",
"Снег, дождь, солнце, тучи — всё это природные явления. Некоторые из них сопровождаются звуками, и их можно передать в музыке.": "Schnee, Regen, Sonne, Wolken – das alles sind Naturerscheinungen. Manche von ihnen sind von Geräuschen begleitet, und man kann sie in der Musik darstellen.",
"Ударные инструменты": "Schlaginstrumente",
"Ударные инструменты — это инструменты, у которых звук получается с помощью удара. По-казахски они называются «соқпалы аспаптар».": "Schlaginstrumente sind Instrumente, bei denen der Klang durch einen Schlag entsteht. Auf Kasachisch heißen sie „соқпалы аспаптар“.",
"Две группы ударных": "Zwei Gruppen von Schlaginstrumenten",
