"Эдвард Григ": "Edvard Grieg",
"Эдвард Григ — норвежский композитор. Он написал сюиту «Пер Гюнт» к театральной пьесе Генрика Ибсена.": "Edvard Grieg war ein norwegischer Komponist. Er schrieb die Suite „Peer Gynt“ zum Theaterstück von Henrik Ibsen.",
"Сюита «Пер Гюнт»": "Suite „Peer Gynt“",
"В ней есть пьесы «Утро» и «В пещере горного короля». Григ показывает в музыке утреннюю природу и жителей подземного царства.": "Darin gibt es die Stücke „Morgenstimmung“ und „In der Halle des Bergkönigs“. Grieg zeigt in der Musik die Natur am Morgen und die Bewohner des unterirdischen Reiches.",
"Природа и инструменты": "Natur und Instrumente",
"Барсик просит тебя разложить карточки: что относится к природным явлениям, а что — к ударным инструментам.": "Barsik bittet dich, die Karten zu sortieren: Was gehört zu den Naturerscheinungen und was zu den Schlaginstrumenten.",
