"Различать подгруппы струнных инструментов и называть произведения о воде и грозе.": "Die Untergruppen der Saiteninstrumente unterscheiden und Werke über Wasser und Gewitter nennen.",
"Струнные инструменты": "Saiteninstrumente",
"Это самая многочисленная группа инструментов. Их называют основой симфонического оркестра.": "Das ist die größte Gruppe von Instrumenten. Man nennt sie die Grundlage des Sinfonieorchesters.",
"Народные струнные": "Volkstümliche Saiteninstrumente",
"Семейство народных струнных инструментов тоже очень разнообразно. Все струнные инструменты в мире условно делят на три подгруппы.": "Auch die Familie der volkstümlichen Saiteninstrumente ist sehr vielfältig. Alle Saiteninstrumente der Welt teilt man ganz grob in drei Untergruppen ein.",
"Щипковые": "Zupfinstrumente",
"Звук получают, защипывая струну пальцами или специальной пластинкой — плектром. Это домбра, гитара, арфа.": "Den Klang erzeugt man, indem man die Saite mit den Fingern oder mit einem besonderen Plättchen, dem Plektron, zupft. Das sind Dombra, Gitarre, Harfe.",
"Смычковые и ударные": "Streich- und Schlaginstrumente",
"У смычковых звук извлекают смычком из конского волоса: виолончель, кобыз. У ударных по струнам бьют палочками или молоточками: фортепиано, цимбалы.": "Bei den Streichinstrumenten erzeugt man den Klang mit einem Bogen aus Rosshaar: Cello, Kobyz. Bei den Schlaginstrumenten schlägt man mit Stäbchen oder Hämmerchen auf die Saiten: Klavier, Zimbal.",
"Эолова арфа": "Äolsharfe",
"Её струны звучат от колебания воздуха, и музыкант ей не нужен. Это деревянный ящик с отверстием, внутри которого натянуты струны.": "Ihre Saiten klingen durch das Schwingen der Luft, und man braucht dafür keinen Musiker. Das ist ein Holzkasten mit einem Loch, in dem Saiten gespannt sind.",
"Разложи струнные инструменты по подгруппам": "Sortiere die Saiteninstrumente nach Untergruppen",
"Определи, к какой подгруппе относится инструмент или способ звукоизвлечения.": "Bestimme, zu welcher Untergruppe das Instrument oder die Art der Klangerzeugung gehört.",
"В какую подгруппу относится?": "Zu welcher Untergruppe gehört es?",
