"Духовые инструменты": "Blasinstrumente",
"Это инструменты, которые звучат благодаря воздуху, который вдувает музыкант. Они делятся на три группы: медные, деревянные и клавишные.": "Das sind Instrumente, die durch die Luft klingen, die der Musiker hineinbläst. Sie teilen sich in drei Gruppen: Blechblasinstrumente, Holzblasinstrumente und Tasteninstrumente.",
"Медные и деревянные": "Blech- und Holzblasinstrumente",
"К медным относятся труба, валторна, туба, горн, фанфары. К деревянным — дудка, флейта, саксофон, кларнет, фагот, балабан и зурна.": "Zu den Blechblasinstrumenten gehören Trompete, Horn, Tuba, Signalhorn, Fanfaren. Zu den Holzblasinstrumenten gehören Pfeife, Flöte, Saxofon, Klarinette, Fagott, Balaban und Surna.",
"Клавишные духовые": "Tasten-Blasinstrumente",
"К клавишным духовым относятся фисгармония, аккордеон, мелодика, баян и орган.": "Zu den Tasten-Blasinstrumenten gehören Harmonium, Akkordeon, Melodica, Bajan und Orgel.",
"Сценические эффекты": "Bühneneffekte",
"Так называют звуковое и световое сопровождение, иллюзии движения и превращения в спектакле, концерте или шоу. Слово пришло из латыни и означает «исполнение».": "So nennt man Ton- und Lichtbegleitung, Illusionen von Bewegung und Verwandlung in einem Theaterstück, Konzert oder einer Show. Das Wort kommt aus dem Lateinischen und bedeutet „Ausführung“.",
