"Различать, как музыка передаёт дикий и укрощённый огонь, и называть произведения С. Прокофьева и П.И. Чайковского.": "Unterscheiden, wie die Musik wilde und gezähmte Feuer darstellt, und Werke von S. Prokofjew und P. I. Tschaikowski nennen.",
"Огненный смерч": "Feuersturm",
"Это очень яркое, но очень опасное природное явление. Чаще всего оно возникает в горящем лесу, а ветер там сильнее 160 километров в час.": "Das ist eine sehr helle, aber sehr gefährliche Naturerscheinung. Meistens entsteht sie in einem brennenden Wald, und der Wind ist dort stärker als 160 Kilometer pro Stunde.",
"Прокофьев и «Каменный цветок»": "Prokofjew und „Die steinerne Blume“",
"Композитор С. Прокофьев в балете «Каменный цветок» изобразил музыкой похожее явление. Танец Огневушки-поскакушки передаёт неуправляемый характер огненного вихря.": "Der Komponist S. Prokofjew stellte im Ballett „Die steinerne Blume“ mit Musik eine ähnliche Erscheinung dar. Der Tanz der Ognewuschka-Poskakuschka zeigt den unbändigen Charakter des Feuerwirbels.",
"Укрощённый огонь": "Gezähmtes Feuer",
"Человек научился управлять огнём: он обогревает и освещает жильё. Такой огонь спокойный и доброжелательный.": "Der Mensch hat gelernt, das Feuer zu beherrschen: Es wärmt und beleuchtet die Wohnung. Ein solches Feuer ist ruhig und freundlich.",
"Чайковский и «У камелька»": "Tschaikowski und „Am Kamin“",
"Пьеса «У камелька» входит в цикл «Времена года» П.И. Чайковского. В ней музыка передаёт спокойный, добрый огонь и чувство тепла.": "Das Stück „Am Kamin“ gehört zum Zyklus „Die Jahreszeiten“ von P. I. Tschaikowski. Darin zeigt die Musik ein ruhiges, gutes Feuer und das Gefühl von Wärme.",
"Огонь и безопасность": "Feuer und Sicherheit",
"Огонь может стать причиной пожара, поэтому очень важно соблюдать правила пожарной безопасности. Спички — не игрушка, а огонь — не забава!": "Feuer kann einen Brand verursachen, deshalb ist es sehr wichtig, die Brandschutzregeln einzuhalten. Streichhölzer sind kein Spielzeug, und Feuer ist kein Spaß!",
