"Объяснять, что такое программная музыка, и называть примеры музыки, изображающей природу.": "Erklären, was Programmmusik ist, und Beispiele für Musik nennen, die die Natur darstellt.",
"Музыкальная живопись": "Musikalische Malerei",
"Люди всегда делились впечатлениями от увиденного и услышанного. Есть даже выражение «музыкальная живопись» — музыка, которая рисует картины природы.": "Die Menschen haben schon immer ihre Eindrücke von dem geteilt, was sie gesehen und gehört haben. Es gibt sogar den Ausdruck «musikalische Malerei» – Musik, die Bilder der Natur malt.",
"Цикл П. Чайковского «Времена года» состоит из 12 пьес. Каждая пьеса — образ одного месяца года, чаще всего через пейзаж.": "Der Zyklus «Die Jahreszeiten» von P. Tschaikowski besteht aus 12 Stücken. Jedes Stück ist ein Bild eines Monats im Jahr, meistens durch eine Landschaft.",
"Настроение сезона": "Die Stimmung der Jahreszeit",
"В небольших пьесах-акварелях отражено настроение сезона: зимние грёзы, весенняя свежесть, летнее раздолье, осенняя грусть.": "In den kleinen Stücken, die wie Aquarelle sind, spiegelt sich die Stimmung der Jahreszeit wider: Winterträume, Frühlingsfrische, Sommerweite, Herbstwehmut.",
"Программная музыка": "Programmmusik",
"Это академическая музыка без слов, то есть инструментальная. Но к ней есть словесное указание на содержание: название или пояснение.": "Das ist klassische Musik ohne Worte, also Instrumentalmusik. Aber es gibt einen Hinweis in Worten auf den Inhalt: einen Titel oder eine Erklärung.",
"Заголовок и эпиграф": "Titel und Motto",
"Перед каждой из 12 миниатюр Чайковского есть заголовок и эпиграф — строчки из стихов русских поэтов. Они раскрывают характер музыки. Один из таких эпиграфов взят у А. Майкова.": "Vor jeder der 12 Miniaturen von Tschaikowski stehen ein Titel und ein Motto – Zeilen aus Gedichten russischer Dichter. Sie zeigen den Charakter der Musik. Eines dieser Mottos stammt von A. Maikow.",
