"Урок 22. Музыка-призыв": "Lektion 22. Musik als Aufruf",
"Музыка-призыв": "Musik als Aufruf",
"Объяснять, как музыка призывает беречь природу, и называть песни и их авторов.": "Erklären, wie Musik dazu aufruft, die Natur zu schützen, und Lieder und ihre Autoren nennen.",
"Что такое призыв": "Was ein Aufruf ist",
"Призыв — это обращение, которое зовёт к действию. По-казахски это «шакыру», по-английски — «call».": "Ein Aufruf ist eine Ansprache, die zum Handeln auffordert. Auf Kasachisch heißt es «schakyru», auf Englisch «call».",
"Музыка, которая зовёт": "Musik, die ruft",
"Многие музыкальные произведения не просто украшают нашу жизнь. Они становятся руководством к действию и помогают человеку сделать правильный выбор.": "Viele Musikwerke verschönern unser Leben nicht nur. Sie werden zur Anleitung zum Handeln und helfen dem Menschen, die richtige Wahl zu treffen.",
"Экологическая тема": "Das Umweltthema",
"В музыке бывает экологическая тема — это охрана окружающей среды. Песни напоминают нам, что природу нужно беречь.": "In der Musik gibt es das Umweltthema – das ist der Schutz der Umwelt. Lieder erinnern uns daran, dass man die Natur schützen muss.",
"«Песня о земной красоте»": "«Lied von der Schönheit der Erde»",
"Эту песню написал Я. Дубравин. Она о красоте природы и о доброте, которой нужно делиться.": "Dieses Lied hat J. Dubrawin geschrieben. Es handelt von der Schönheit der Natur und von der Güte, die man teilen soll.",
"«Не дразните собак»": "«Ärgert die Hunde nicht»",
"Эта песня из кинофильма «Происшествие». Музыку написал Е. Птичкин, слова — М. Пляцковский. Песня призывает добро относиться к животным и красоте земли.": "Dieses Lied stammt aus dem Spielfilm «Der Vorfall». Die Musik schrieb J. Ptitschkin, den Text M. Pljazkowski. Das Lied ruft dazu auf, freundlich zu den Tieren zu sein und die Schönheit der Erde zu achten.",
"Береги природу": "Schütze die Natur",
"Барсик спрашивает: что помогает природе и животным, а что им вредит? Разложи карточки.": "Barsik fragt: Was hilft der Natur und den Tieren, und was schadet ihnen? Ordne die Karten zu.",
"Так поступает друг природы": "So handelt ein Freund der Natur",
"Так поступать нельзя": "So darf man nicht handeln",
"Посадить дерево": "Einen Baum pflanzen",
"Пословица говорит: кто не сажал дерева, тому не лежать в тени.": "Das Sprichwort sagt: Wer keinen Baum gepflanzt hat, wird nicht im Schatten liegen.",
"Беречь молодую поросль": "Junge Triebe schützen",
"Из неё вырастут большие деревья.": "Aus ihnen wachsen große Bäume.",
"Насыпать птицам зерно и крошки": "Den Vögeln Körner und Krümel streuen",
"Так мы заботимся о птицах.": "So sorgen wir für die Vögel.",
"Любоваться красотой земли и беречь её": "Die Schönheit der Erde bewundern und sie schützen",
"Это призыв песни о земной красоте.": "Das ist der Aufruf des Liedes von der Schönheit der Erde.",
"Дразнить собак": "Hunde ärgern",
"Песня призывает так не делать.": "Das Lied ruft dazu auf, das nicht zu tun.",
