"Мой любимец": "Mein Liebling",
"Объяснять, что такое нотное переложение, и называть музыкальные произведения о любимых животных.": "Erklären, was eine Bearbeitung (Arrangement) ist, und Musikwerke über geliebte Tiere nennen.",
"Конь в музыке": "Das Pferd in der Musik",
"У казахского народа самым любимым и почитаемым животным всегда был конь, скакун. Многие композиторы рисовали музыкой его стремительные, неудержимые скачки.": "Beim kasachischen Volk war das Pferd, der Renner, schon immer das liebste und am meisten verehrte Tier. Viele Komponisten haben mit Musik seinen stürmischen, unaufhaltsamen Galopp gemalt.",
"Курмангазы и «Адай»": "Kurmangazy und «Adai»",
"Великий казахский композитор Курмангазы создал музыкальную картину «Адай». В ней не просто скачки: он показал мужественный, героический дух древнего казахского рода Адай.": "Der große kasachische Komponist Kurmangazy schuf das Musikbild «Adai». Darin geht es nicht nur um Galopp: Er zeigte den mutigen, heldenhaften Geist des alten kasachischen Stammes Adai.",
"Одно произведение — разное исполнение": "Ein Werk – verschiedene Aufführungen",
"Кюй «Адай» можно услышать в трёх исполнениях: на домбре, в оркестре и с электронными инструментами. Произведение одно, а исполнение разное.": "Den Kuy «Adai» kann man in drei Aufführungen hören: auf der Dombra, im Orchester und mit elektronischen Instrumenten. Das Werk ist dasselbe, die Aufführung ist verschieden.",
"Что такое переложение": "Was eine Bearbeitung ist",
"Переложение — это музыкальное произведение, изложенное в иной форме. Барсик говорит: мелодия та же, а звучит по-новому!": "Eine Bearbeitung ist ein Musikwerk, das in einer anderen Form dargestellt wird. Barsik sagt: Die Melodie ist dieselbe, aber sie klingt neu!",
"Песни о любимцах и о мире": "Lieder über Lieblinge und über die Welt",
"У всех народов мира есть песни о домашних любимцах, например английская народная песня «Котятки и перчатки». А песня Л. Квинт «Здравствуй, мир» — о жеребёнке и о мире вокруг. Слово «мир» по-казахски — әлем.": "Alle Völker der Welt haben Lieder über Haustiere, zum Beispiel das englische Volkslied «Die kleinen Kätzchen und die Handschuhe». Und das Lied von L. Kwint «Hallo, Welt» handelt von einem Fohlen und von der Welt ringsum. Das Wort «Welt» heißt auf Kasachisch әлем.",
"Чья это песня или кюй?": "Wessen Lied oder Kuy ist das?",
