"Родина по-казахски — Отан, по-английски — Homeland. Это страна, где мы живём и которую любим.": "Heimat heißt auf Kasachisch Otan und auf Englisch Homeland. Das ist das Land, in dem wir leben und das wir lieben.",
"Любовь к Родине": "Liebe zur Heimat",
"В народе говорят, что любовь к Родине начинается у семейного очага, то есть в семье и дома.": "Im Volk sagt man, dass die Liebe zur Heimat am heimischen Herd beginnt, das heißt in der Familie und zu Hause.",
"Красота родного края": "Die Schönheit der Heimat",
"В песнях, кюях, сказаниях и сказках авторы воспевали красоту родного края и призывали сохранять и оберегать её.": "In Liedern, Kuys, Sagen und Märchen besangen die Autoren die Schönheit ihrer Heimat und riefen dazu auf, sie zu bewahren und zu schützen.",
"Кюй «Алатау»": "Das Kuj «Alatau»",
"Композитор Курмангазы Сагырбайулы изобразил в кюе величественные горные вершины и красивую природу Заилийского Алатау. Кюй можно услышать в исполнении на домбре и в оркестровом варианте.": "Der Komponist Kurmangazy Sagyrbaiuly hat in einem Kuy die majestätischen Berggipfel und die schöne Natur des Trans-Ili-Alatau dargestellt. Den Kuy kann man auf der Dombra und in einer Orchesterfassung hören.",
"Что мы бережём": "Was wir bewahren",
"Люди стараются сохранить не только природные богатства, но и культурное наследие своего народа. Песня «Наурыз жыры» (музыка М. Жаманкуловой) — о празднике Наурыз.": "Die Menschen bemühen sich, nicht nur die Naturschätze, sondern auch das kulturelle Erbe ihres Volkes zu bewahren. Das Lied „Nauryz zhyry“ (Musik von M. Zhamankulova) handelt vom Nauryz-Fest.",
"Разложи по произведениям": "Ordne den Werken zu",
"Барсик просит разобраться, что относится к кюю, а что к песне.": "Barsik bittet darum, zu klären, was zum Kuy gehört und was zum Lied.",
"К какому произведению относится?": "Zu welchem Werk gehört das?",
