"Урок 26. Как прекрасен этот мир": "Lektion 26. Wie schön ist diese Welt",
"Как прекрасен этот мир": "Wie schön ist diese Welt",
"Объяснять, как с помощью музыкальных произведений можно показать красоту окружающего мира и призвать беречь его.": "Erklären, wie man mit Musikwerken die Schönheit der Welt um uns zeigen und dazu aufrufen kann, sie zu schützen.",
"Берегём мир": "Wir schützen die Welt",
"Если все люди на планете будут беречь и охранять окружающую среду, то мир вокруг нас будет ярким и многообразным.": "Wenn alle Menschen auf dem Planeten die Umwelt schützen und bewahren, dann wird die Welt um uns herum bunt und vielfältig sein.",
"Путешествие": "Die Reise",
"Слово «путешествие» по-казахски «саяхат», а по-английски «voyage». Музыка тоже может отправить нас в путешествие по красивым местам.": "Das Wort „Reise“ heißt auf Kasachisch „sayahat“ und auf Englisch „voyage“. Auch Musik kann uns auf eine Reise zu schönen Orten schicken.",
"Песня Д. Тухманова": "Das Lied von D. Tuchmanow",
"Песня «Как прекрасен этот мир» написана композитором Д. Тухмановым. В ней важно услышать, как солирующий голос и подголоски дополняют друг друга.": "Das Lied „Wie schön ist diese Welt“ wurde vom Komponisten D. Tuchmanow geschrieben. Wichtig ist, zu hören, wie sich die Solostimme und die Nebenstimmen ergänzen.",
"Поющий бархан": "Die singende Düne",
"«Поющий бархан» — природная достопримечательность Казахстана. Он находится в 180 км от города Алматы, на территории Государственного Национального природного парка «Алтынемель».": "Die „Singende Düne“ ist eine Naturattraktion Kasachstans. Sie liegt 180 km von der Stadt Almaty entfernt, auf dem Gebiet des staatlichen Nationalparks „Altyn-Emel“.",
"Экологический туризм": "Ökotourismus",
"Термин «экологический туризм» в 1983 году ввёл мексиканский экономист-эколог Гектор Цебаллос-Ласкурейн. Он призывал туристов не оставлять после отдыха загрязнения и уважать культурные традиции народа.": "Den Begriff „Ökotourismus“ führte 1983 der mexikanische Ökonom und Umweltschützer Héctor Ceballos-Lascuráin ein. Er rief die Touristen dazu auf, nach dem Urlaub keinen Schmutz zu hinterlassen und die kulturellen Traditionen des Volkes zu achten.",
"Разложи темы по страницам журнала": "Ordne die Themen den Seiten der Zeitschrift zu",
"Устный журнал «Как прекрасен этот мир» состоит из страниц, и у каждой своя тема. Определи, к какой странице относится сообщение.": "Die mündliche Zeitschrift „Wie schön ist diese Welt“ besteht aus Seiten, und jede hat ihr eigenes Thema. Bestimme, zu welcher Seite die Nachricht gehört.",
"К какой странице журнала относится сообщение?": "Zu welcher Seite der Zeitschrift gehört die Nachricht?",
