"17-сабақ. Музыкадағы таң көріністері": "Lektion 17. Morgenbilder in der Musik",
"Музыкадағы таң көріністері": "Morgenbilder in der Musik",
"Музыкадағы таң көріністерін сипаттап, М. Мусоргскийдің, Э. Григтің және С. Еркімбековтің шығармаларын ажырата білу.": "Morgenbilder in der Musik beschreiben und die Werke von M. Mussorgski, E. Grieg und S. Erkimbekow unterscheiden können.",
"Композиторға не әсер етеді?": "Was beeinflusst einen Komponisten?",
"Композиторлар шабыттан, қиялдан, туған жеріне, халқына және табиғатына деген сүйіспеншіліктен шығарма жазады. Біз сүйіспеншілігімізді сөзбен айтсақ, олар музыкамен баяндайды.": "Komponisten schreiben ihre Werke aus Inspiration, Fantasie und aus Liebe zu ihrer Heimat, ihrem Volk und ihrer Natur. Wenn wir unsere Liebe mit Worten ausdrücken, erzählen sie davon mit Musik.",
"Модест Петрович Мусоргский (1839–1881) — орыстың ұлы композиторы. Ол «Хованщина» операсына жазған «Мәскеу өзеніндегі таң» кіріспесімен танымал: онда арайлап атқан таң бейнеленеді.": "Modest Petrowitsch Mussorgski (1839–1881) ist ein großer russischer Komponist. Er ist bekannt durch das Vorspiel „Morgendämmerung an der Moskwa“ zu seiner Oper „Chowanschtschina“: Darin wird der rötlich anbrechende Morgen dargestellt.",
"Эдвард Григ (1843–1907) — Норвегияның әйгілі композиторы, пианист, дирижёр. Ол «Пер Гюнт» сюитасының «Таң» шығармасында туған жерінің табиғатын, таң шапағын көркемдеуіш құралдар арқылы суреттеген.": "Edvard Grieg (1843–1907) ist ein berühmter norwegischer Komponist, Pianist und Dirigent. In dem Stück „Morgenstimmung“ aus der „Peer-Gynt-Suite“ hat er die Natur seiner Heimat und das Morgenlicht mit künstlerischen Mitteln gemalt.",
"С. Еркімбеков": "S. Yerkimbekov",
"Серік Еркімбеков — белгілі композитор, ҚР еңбек сіңірген қайраткері. Оның «Отан таңы» шығармасы туған жердің сұлулығын көрсетеді.": "Serik Erkimbekow ist ein bekannter Komponist und Verdienter Würdenträger der Republik Kasachstan. Sein Werk „Morgen der Heimat“ zeigt die Schönheit der Heimat.",
"Жаңа сөздер": "Neue Wörter",
"Опера — вокалдық және аспаптық музыканы, театр өнерін біріктіретін жанр. Сюита — бір идеяға бағындырылған әртүрлі пьесалардан құралған шығарма. Интерпретация — орындаушының шығарманы көркем түсіндіруі.": "Oper – eine Gattung, die vokale und instrumentale Musik und Theaterkunst verbindet. Suite – ein Werk aus verschiedenen Stücken, die einer Idee untergeordnet sind. Interpretation – die künstlerische Deutung eines Werkes durch den Ausführenden.",
