"Айту: А.Н. Скрябиннің «Прометей» симфониялық поэмасы мен «Жалын биі», «Жел» шығармаларында от пен жел қалай бейнеленетінін түсіндіру.": "Erzählen: erklären, wie Feuer und Wind in A. N. Skrjabins sinfonischer Dichtung „Prometheus“ und in den Werken „Flammentanz“ und „Wind“ dargestellt werden.",
"От — өмір символы": "Feuer – ein Symbol des Lebens",
"Адам отсыз өмір сүре алмайды. От ежелден өмірдің және жылулықтың символы болып саналады.": "Der Mensch kann ohne Feuer nicht leben. Feuer gilt seit alters her als Symbol des Lebens und der Wärme.",
"«Прометей» поэмасы": "Die Dichtung „Prometheus“",
"Бұл — А.Н. Скрябиннің симфониялық поэмасы. Оның екінші аты — «Поэма огня», яғни «От туралы поэма». Ол 1910 жылы жазылған.": "Das ist eine sinfonische Dichtung von A. N. Skrjabin. Ihr zweiter Name ist „Poem des Feuers“, das heißt „Gedicht vom Feuer“. Sie wurde 1910 geschrieben.",
"Прометей туралы аңыз": "Die Sage von Prometheus",
"Поэма ежелгі грек аңызына негізделген. Прометей Олимптен отты рұқсатсыз алып кетіп, адамдарға сыйлаған. Сол үшін құдайлар оны жартасқа мәңгі байлап қойған.": "Die Dichtung beruht auf einer alten griechischen Sage. Prometheus nahm das Feuer ohne Erlaubnis vom Olymp und schenkte es den Menschen. Dafür fesselten ihn die Götter für immer an einen Felsen.",
"Жарық партиясы": "Die Lichtstimme",
"Скрябин оркестрге хор мен «жарық партиясын» қосқан. Композитордың ойынша, музыкамен бірге түрлі түсті прожектор сәулелері ауысып тұруы керек.": "Skrjabin hat dem Orchester einen Chor und eine „Lichtstimme“ hinzugefügt. Nach der Vorstellung des Komponisten sollen zur Musik bunte Scheinwerferstrahlen wechseln.",
"Симфониялық поэма": "Sinfonische Dichtung",
"Симфониялық поэма — бір бөлімді симфониялық музыка жанры. Бұл — оркестрге арналған бағдарламалық шығарма.": "Die sinfonische Dichtung ist eine Gattung einsätziger sinfonischer Musik. Sie ist ein Programmwerk für Orchester.",
