"Музыкадағы табиғат құбылыстары (жалғасы)": "Naturerscheinungen in der Musik (Fortsetzung)",
"Музыка арқылы су мен желдің бейнесін елестетіп, шығармаларды суреттермен және билермен салыстыра білу.": "Sich durch Musik das Bild von Wasser und Wind vorstellen und die Werke mit Bildern und Tänzen vergleichen können.",
"Су мен жел – табиғат құбылыстары": "Wasser und Wind – Naturerscheinungen",
"«Сусыз өмір жоқ», «Жел ауа тазартады» дейді. Әр табиғат құбылысының адам өмірінде өз орны бар.": "Man sagt: „Ohne Wasser gibt es kein Leben“, „Der Wind reinigt die Luft“. Jede Naturerscheinung hat ihren Platz im Leben der Menschen.",
"«Ақ бұлақ әуені»": "„Melodie der Weißen Quelle“",
"Бұл шығарманың музыкасын С. Еркімбеков жазған. Тыңдағанда көз алдыңа судың көріністері елестейді.": "Die Musik dieses Werkes hat S. Erkimbekow geschrieben. Beim Zuhören stellst du dir Bilder von Wasser vor.",
"«Жел әуені»": "„Windmelodie“",
"Бұл шығарманың да музыкасын С. Еркімбеков жазған. Композитор музыка арқылы желдің уілін бейнелеген.": "Auch die Musik dieses Werkes hat S. Erkimbekow geschrieben. Der Komponist hat das Heulen des Windes mit Musik dargestellt.",
"Музыка мен суретті салыстыру": "Musik und Bild vergleichen",
"«Ақ бұлақ әуенін» Ө. Қастеевтің «Өмір-өзен» картинасымен, «Жел әуенін» И.В. Ломанованың «Күзгі жел» картинасымен салыстырамыз. Айырмашылығы мен ұқсастығын табамыз.": "Wir vergleichen die „Melodie der Weißen Quelle“ mit dem Gemälde „Fluss des Lebens“ von Ö. Kasteew und die „Windmelodie“ mit dem Gemälde „Herbstwind“ von I. W. Lomanowa. Wir finden Unterschiede und Gemeinsamkeiten.",
"«Жел» әнінің өлеңін Н. Әлімқұлов, әнін М. Маңғытаев жазған. Оны мәнерлеп орындауға тырысамыз.": "Den Text des Liedes „Wind“ hat N. Alimkulow geschrieben, die Melodie M. Mangytajew. Wir versuchen, es ausdrucksvoll zu singen.",
"Су және жел тақырыбы": "Thema Wasser und Wind",
