"20-сабақ. Музыкадағы жыл мезгілдері": "Lektion 20. Jahreszeiten in der Musik",
"Музыкадағы жыл мезгілдері": "Jahreszeiten in der Musik",
"Жыл мезгілдеріне арналған А. Вивальди концерттерін және оркестр туралы негізгі ұғымдарды (оркестр, дирижёр, партитура, концерт) атай білу.": "Die Konzerte von A. Vivaldi über die Jahreszeiten und die wichtigsten Begriffe zum Orchester (Orchester, Dirigent, Partitur, Konzert) nennen können.",
"Жылдың төрт мезгілі": "Die vier Jahreszeiten",
"Қыс, көктем, жаз, күз бірінен кейін бірі ауысып отырады. Әр мезгілдің өз әсемдігі бар, сондықтан оған арнап өлеңдер, әндер мен музыкалық шығармалар жазылған.": "Winter, Frühling, Sommer und Herbst wechseln einander ab. Jede Jahreszeit hat ihre eigene Schönheit, deshalb wurden ihr zu Ehren Gedichte, Lieder und Musikwerke geschrieben.",
"Вивальди (1678–1741) – итальян композиторы, асқан шебер скрипкашы, дирижёр. Ол Венеция қаласында дүниеге келген.": "Vivaldi (1678–1741) war ein italienischer Komponist, ein großer Meister der Violine und Dirigent. Er wurde in der Stadt Venedig geboren.",
"«Жыл мезгілдері» концерттері": "Die Konzerte „Die Jahreszeiten“",
"Вивальдидің ең танымал шығармасы – «Жыл мезгілдері» деп аталатын скрипкаға арналған төрт концерт. Олар: «Көктем», «Жаз», «Күз», «Қыс».": "Vivaldis bekanntestes Werk sind die vier Konzerte für Violine mit dem Titel „Die Jahreszeiten“. Es sind: „Frühling“, „Sommer“, „Herbst“, „Winter“.",
"«Шат көңіл» әні": "Das Lied „Frohsinn“",
"Бұл әннің өлеңін Б. Тәжібаев жазған, әнін С. Еркімбеков шығарған. Ән вальс ырғағымен орындалады, көңілді, жарқын.": "Den Text dieses Liedes hat B. Taschibajew geschrieben, die Melodie hat S. Erkimbekow komponiert. Das Lied wird im Walzerrhythmus gesungen, es ist fröhlich und hell.",
"Оркестр және дирижёр": "Orchester und Dirigent",
"Оркестр – музыкалық шығармаларды орындайтын аспаптар ұжымы. Дирижёр – музыканттар ұжымын басқарады және шығарманың әдемі орындалуына жауап береді.": "Das Orchester ist eine Gruppe von Instrumenten, die Musikwerke aufführt. Der Dirigent leitet die Gruppe der Musiker und ist dafür verantwortlich, dass das Werk schön gespielt wird.",
