"21-сабақ. Музыкадағы жыл мезгілдері (жалғасы)": "Lektion 21. Jahreszeiten in der Musik (Fortsetzung)",
"Музыкадағы жыл мезгілдері (жалғасы)": "Jahreszeiten in der Musik (Fortsetzung)",
"Жыл мезгілдері туралы шығармаларды таныру, канон, оркестр, дирижёр, симфониялық поэма және сюита ұғымдарын түсіндіру.": "Werke über die Jahreszeiten erkennen; die Begriffe Kanon, Orchester, Dirigent, sinfonische Dichtung und Suite erklären.",
"Жыл – он екі ай": "Das Jahr – zwölf Monate",
"Жыл мезгілдеріне арналған ән мен музыкалық шығарма көп. Домбырашы, композитор Төлепберген Тоқжанов домбыраға арнап «Жыл – он екі ай» пьесаларын жазған, онда он екі айдың ерекшелігі суреттелген.": "Es gibt viele Lieder und Musikstücke über die Jahreszeiten. Der Dombra-Spieler und Komponist Tolepbergen Tokzhanov hat für die Dombra die Stücke „Zhyl – on eki ai“ geschrieben, in denen die Besonderheiten der zwölf Monate dargestellt werden.",
"«Жұмбақ әуендер» ойыны": "Das Spiel „Rätselhafte Melodien“",
"Тыңдалған музыкаға қарай шығарма атын түсі сәйкес келетін қағазбен көрсетесің: «Ақпан – Бұрқасын» – ақ, «Қыркүйек – Күзгі той» – сары, «Сәуір – Көктемгі тамшылар» – жасыл, «Шілде – Жаз биі» – қызыл. Түстерді дұрыс көрсеткен топ жеңімпаз болады.": "Je nach der Musik, die du hörst, zeigst du den Titel des Stücks mit dem passenden farbigen Papier: „Akpan – Burqasyn“ – weiß, „Qyrkuiek – Kuzgi toi“ – gelb, „Sauir – Koktemgi tamshylar“ – grün, „Shilde – Zhaz biі“ – rot. Die Gruppe, die die Farben richtig zeigt, gewinnt.",
"Канон": "Kanon",
"Әнді орындаудың бір тәсілі – канон. Әнді топтарға бөліп, шумақты кезектесіп, бірінен кейін бірі бастап айтады. «Жау-жау, жаңбыр!» әнінің сөзін Ш. Сариев, әнін К. Дүйсекеев жазған.": "Eine Art, ein Lied vorzutragen, ist der Kanon. Man teilt das Lied in Gruppen auf, und die Gruppen beginnen die Strophe nacheinander. Den Text des Liedes „Zhau-zhau, zhanbyr!“ hat Sh. Sariyev geschrieben, die Melodie K. Duisekeev.",
"Оркестр – түрлі музыкалық аспаптарда шығармалар орындайтын ұжым. Дирижёр – музыкант-орындаушылар ұжымын басқаратын маман.": "Ein Orchester ist eine Gruppe, die Stücke auf verschiedenen Musikinstrumenten spielt. Ein Dirigent ist ein Fachmann, der eine Gruppe von Musikern leitet.",
"Симфониялық поэма және сюита": "Sinfonische Dichtung und Suite",
"Симфониялық поэма – бір бөлімді, симфониялық оркестрге арналған бағдарламалық шығарма. Сюита – бір идеяға бағындырылған, әртүрлі пьесадан құрастырылған музыкалық шығарма.": "Eine sinfonische Dichtung ist ein einsätziges Programmwerk für ein Sinfonieorchester. Eine Suite ist ein Musikstück, das aus verschiedenen Stücken besteht, die einer Idee untergeordnet sind.",
