"22-сабақ. Арал тағдыры — ел тағдыры": "Lektion 22. Das Schicksal des Aral – das Schicksal des Landes",
"Арал тағдыры — ел тағдыры": "Das Schicksal des Aral – das Schicksal des Landes",
"Арал мәселесі туралы музыка мен суреттің көмегімен айта білу және Қ. Сайжанның күйін, Т. Шевченконың пейзаждарын, «Аралым» әнін ажырату.": "Mithilfe von Musik und Bildern über das Aralproblem sprechen können und das Kuy von K. Saizhan, die Landschaften von T. Schewtschenko und das Lied „Aralym“ unterscheiden.",
"Арал мәселесі": "Das Aralproblem",
"Арал теңізі тартылып барады. Желмен ұшқан ащы тұз табиғатқа да, адам денсаулығына да зиян келтіреді.": "Der Aralsee trocknet aus. Das vom Wind verwehte bittere Salz schadet der Natur und der Gesundheit der Menschen.",
"Бүкіл әлемнің қайғысы": "Der Kummer der ganzen Welt",
"Арал мәселесі тек Қазақстан үшін ғана емес, басқа мемлекеттер үшін де өзекті. Отандық және шетелдік ғалымдар Аралды қайта толтыру жолдарын қарастыруда.": "Das Aralproblem ist nicht nur für Kasachstan wichtig, sondern auch für andere Staaten. Einheimische und ausländische Wissenschaftler suchen nach Wegen, den Aralsee wieder zu füllen.",
"«Арал тағдыры» күйі": "Das Kuy „Aral tagdyry“",
"Бұл — Қ. Сайжанның күйі. Күйдің орындалуы адамның мұңды, қайғылы сезімдерін білдіреді, композитор тыңдаушыға маңызды ойды жеткізуге тырысқан.": "Das ist ein Kuy von K. Saizhan. Der Vortrag des Kuys drückt traurige, schmerzvolle Gefühle aus, der Komponist wollte dem Zuhörer einen wichtigen Gedanken vermitteln.",
"Тарас Шевченко": "Taras Schewtschenko",
"Тарас Григорьевич Шевченко (1814–1861) — украиннің әйгілі ақыны әрі суретшісі. 1838 жылы Санкт-Петербург қаласының Көркемсурет академиясын бітірген.": "Taras Grigorjewitsch Schewtschenko (1814–1861) war ein berühmter ukrainischer Dichter und Maler. 1838 schloss er die Kunstakademie in der Stadt Sankt Petersburg ab.",
"Шевченко және Арал": "Schewtschenko und der Aral",
"1848 жылы ол А.И. Бутаковтың басшылығымен Арал теңізін зерттеу экспедициясына қатысып, 350-ден астам пейзаж, портрет салған. Маңғыстау облысындағы Түпқараған ауданының орталығы «Форт-Шевченко» деп аталады.": "1848 nahm er unter der Leitung von A. I. Butakow an einer Expedition zur Erforschung des Aralsees teil und zeichnete mehr als 350 Landschaften und Porträts. Das Zentrum des Bezirks Tupkaragan im Gebiet Mangystau heißt „Fort Schewtschenko“.",
