"23-сабақ. Ядролық жарылысқа — «Жоқ» дейміз!": "Lektion 23. Zu Atomexplosionen sagen wir „Nein“!",
"Ядролық жарылысқа — «Жоқ» дейміз!": "Zu Atomexplosionen sagen wir „Nein“!",
"Полигон мен радиация ұғымдарын түсіндіру, «Заман-ай» мен «Ядролық жарылысқа — «Жоқ» дейміз!» әндерінің авторларын атау және әндердің мазмұнын сипаттау.": "Die Begriffe Testgelände und Strahlung erklären, die Autoren der Lieder „Saman-ai“ und „Zu Atomexplosionen sagen wir ‚Nein‘!“ nennen und den Inhalt der Lieder beschreiben.",
"Ядролық қарусыз аймақ": "Atomwaffenfreie Zone",
"Қазақстан өзін «ядролық қарусыз аймақ» деп жариялады. Біздің елдің мақсаты — бейбітшілік пен адамдардың денсаулығын сақтау.": "Kasachstan hat sich zur „atomwaffenfreien Zone“ erklärt. Das Ziel unseres Landes ist es, den Frieden und die Gesundheit der Menschen zu bewahren.",
"Декларация": "Die Erklärung",
"1991 жылы 28 тамызда Декларация қабылданды. Семей полигоны жабылды, ел атом қаруынан бас тарту жолын жалғастырды.": "Am 28. August 1991 wurde die Erklärung angenommen. Das Testgelände Semei wurde geschlossen, und das Land setzte seinen Weg des Verzichts auf Atomwaffen fort.",
"Полигон": "Das Testgelände",
"Полигон — қару-жарақ пен әскери техникаға, көбінесе ядролық сынақ жүргізуге арналған арнайы бөлінген және жабдықталған аймақ.": "Ein Testgelände ist ein besonders ausgewiesenes und ausgerüstetes Gebiet für Waffen und Militärtechnik, meist für Atomtests.",
"Радиация": "Die Strahlung",
"Радиация (өткір радиация) — ядролық жарылыс кезінде тарайтын радиоактивті сәулелер.": "Strahlung (akute Strahlung) sind radioaktive Strahlen, die sich bei einer Atomexplosion ausbreiten.",
"Екі ән": "Zwei Lieder",
"«Заман-ай» әнінің өлеңін Ү. Есдәулет, әнін Т. Мұхамеджанов жазған. «Ядролық жарылысқа — «Жоқ» дейміз!» әнінің өлеңін Р. Наурызбаева, әнін Н. Мирманов жазған.": "Den Text des Liedes „Saman-ai“ hat U. Yesdaulet geschrieben, die Melodie T. Mukhamedzhanov. Den Text des Liedes „Zu Atomexplosionen sagen wir ‚Nein‘!“ hat R. Nauryzbaeva geschrieben, die Melodie N. Mirmanov.",
