"24-сабақ. Ядролық жарылысқа — «Жоқ» дейміз! (жалғасы)": "Lektion 24. Zu Atomexplosionen sagen wir „Nein“! (Fortsetzung)",
"Ядролық жарылысқа — «Жоқ» дейміз! (жалғасы)": "Zu Atomexplosionen sagen wir „Nein“! (Fortsetzung)",
"Балет пен реквием деген не екенін айту, Ғ. Жұбанованың «Хиросима» балетін және «Сакура» әнін тану.": "Sagen können, was Ballett und Requiem sind, und das Ballett „Hiroshima“ von G. Zhubanova und das Lied „Sakura“ erkennen.",
"Ғазиза Жұбанова": "Gaziza Zhubanova",
"Ғазиза Жұбанова (1927–1993) — композитор. Ол Алматы қаласында музыканттар отбасында дүниеге келген. Әкесі — атақты композитор Ахмет Жұбанов.": "Gaziza Zhubanova (1927–1993) war eine Komponistin. Sie wurde in der Stadt Almaty in einer Musikerfamilie geboren. Ihr Vater war der berühmte Komponist Akhmet Zhubanov.",
"Композитордың шығармалары": "Die Werke der Komponistin",
"Ғ. Жұбанова опера, балет, оратория, ән, хор жазған. Оның «Хиросима» балеті Қазақстан музыка өнерінде үлкен жаңалық болды.": "G. Zhubanova schrieb Opern, Ballette, Oratorien, Lieder und Chorwerke. Ihr Ballett „Hiroshima“ war eine große Neuheit in der Musikkunst Kasachstans.",
"Мемлекеттік сыйлық": "Der Staatspreis",
"«Хиросима» балеті үшін Ғ. Жұбановаға 1970 жылы Қазақстанның Мемлекеттік сыйлығы берілді.": "Für das Ballett „Hiroshima“ erhielt G. Zhubanova 1970 den Staatspreis Kasachstans.",
"Балет": "Das Ballett",
"Балет — музыкалық-хореографиялық қойылым. Оның мазмұны, кейіпкерлердің ой-сезімі музыка мен би арқылы көрсетіледі.": "Ein Ballett ist eine musikalisch-choreografische Aufführung. Ihr Inhalt und die Gedanken und Gefühle der Figuren werden durch Musik und Tanz gezeigt.",
"Реквием": "Das Requiem",
"Реквием — көпдауысты, қайғылы музыкалық шығарма. «Хиросима» балетінің соңында реквием-гимн естіледі: музыка жер бетінде ешқашан ядролық жарылыстар болмасын деген тілекті жеткізеді.": "Ein Requiem ist ein mehrstimmiges, trauriges Musikstück. Am Ende des Balletts „Hiroshima“ erklingt eine Requiem-Hymne: Die Musik vermittelt den Wunsch, dass es auf der Erde nie wieder Atomexplosionen geben möge.",
"Кім? Не?": "Wer? Was?",
"Әр карточканы дұрыс топқа орналастыр: композитор, сөзін жазған не аударған адам немесе шығарма атауы.": "Lege jede Karte in die richtige Gruppe: Komponist, Person, die den Text geschrieben oder übersetzt hat, oder Titel eines Werks.",
"Сөзін жазған не аударған": "Hat den Text geschrieben oder übersetzt",
"Шығарма": "Werk",
"«Ядролық жарылысқа — «Жоқ» дейміз!» әнінің музыкасын жазған.": "Hat die Musik des Liedes „Zu Atomexplosionen sagen wir ‚Nein‘!“ geschrieben.",
"«Заман-ай» әнінің музыкасын жазған.": "Hat die Musik des Liedes „Saman-ai“ geschrieben.",
