"Бұрыс. Реквием — қайғылы музыкалық шығарма.": "Falsch. Ein Requiem ist ein trauriges Musikstück.",
"Дұрыс. Балеттің оқиғасы жеке бір отбасының ғана тағдыры емес, бүкіл халықтың қайғысы ретінде баяндалған.": "Richtig. Die Handlung des Balletts wird nicht als Schicksal einer einzelnen Familie erzählt, sondern als Kummer des ganzen Volkes.",
"Бұрыс. «Сакура» — жапонның халық әні.": "Falsch. „Sakura“ ist ein japanisches Volkslied.",
"Дұрыс. Сакура көктемде қызғылт түсті нәзік гүл ашады.": "Richtig. Die Sakura öffnet im Frühling zarte rosa Blüten.",
"Дұрыс. Бұл тілек музыка мен балет арқылы жеткізіледі.": "Richtig. Dieser Wunsch wird durch Musik und Ballett vermittelt.",
"Дұрыс. Балетте жапон халқының қарапайым отбасының тіршілігі бейнеленген.": "Richtig. Im Ballett wird das Leben einer einfachen Familie des japanischen Volkes dargestellt.",
