"25-сабақ. Ел қорғауға дайынбыз!": "Lektion 25. Wir sind bereit, das Land zu verteidigen!",
"Ел қорғауға дайынбыз!": "Wir sind bereit, das Land zu verteidigen!",
"Атап айту: «Сарбаздар жыры» мен «Мәңгілік алау» балетінің авторларын, тақырыбын және ел қорғау туралы музыканың мәнін түсіндіру.": "Nenne die Autoren des «Lieds der Soldaten» und des Balletts «Ewige Flamme», ihr Thema, und erkläre, welche Bedeutung Musik über die Verteidigung des Landes hat.",
"Ата-бабалар аманаты": "Das Vermächtnis der Vorfahren",
"Кім болсақ та, қайда жүрсек те, өз туған жерімізді, табиғатымызды аялап, қорғауымыз керек. Бұл — ата-бабаларымыздың бізге қалдырған аманаты.": "Wer wir auch sind und wo wir auch leben, wir müssen unsere Heimat und die Natur lieben und schützen. Das ist das Vermächtnis, das unsere Vorfahren uns hinterlassen haben.",
"Табиғатты қорғау": "Die Natur schützen",
"Арал теңізі мен Семей полигоны мәселелерін өткен сабақтарда білдік. Жеріміздің табиғатына зиян келіп жатыр, сондықтан елімізді, қоршаған ортаны қорғауға дайын болуымыз керек.": "Über die Probleme des Aralsees und des Testgeländes von Semipalatinsk haben wir in früheren Stunden gelernt. Der Natur unseres Landes wird Schaden zugefügt, deshalb müssen wir bereit sein, unser Land und die Umwelt zu schützen.",
"«Сарбаздар жыры»": "«Lied der Soldaten»",
"Бұл — қазақ сарбаздары туралы ән. Өлеңін А. Асылбек жазған, әнін Н. Айтбаева шығарған. Әнде қайырма бар.": "Das ist ein Lied über kasachische Soldaten. Den Text hat A. Assylbek geschrieben, die Melodie hat N. Aitbajewa komponiert. Das Lied hat einen Refrain.",
"Әннің тақырыбы": "Das Thema des Liedes",
"«Сарбаздар жыры» елін қорғайтын батыл сарбаздарды дәріптейді. Ән тыныштық пен бейбіт өмір арманын жеткізеді.": "Das «Lied der Soldaten» preist mutige Soldaten, die ihr Land verteidigen. Das Lied bringt den Traum von Ruhe und einem friedlichen Leben zum Ausdruck.",
"«Мәңгілік алау» балеті": "Das Ballett «Ewige Flamme»",
"Бұл — бір актілі балеттен үзінді, музыкасын С. Еркімбеков жазған. Балет 12 нөмірден тұрады және соғыс пен бейбітшілік туралы айтады. Ондағы нөмірлердің бірі — «Реквием».": "Das ist ein Auszug aus einem Ballett in einem Akt, die Musik hat S. Erkimbekow geschrieben. Das Ballett besteht aus 12 Nummern und erzählt von Krieg und Frieden. Eine der Nummern ist «Requiem».",
