"26-сабақ. Қоршаған ортамызды сақтайық!": "Lektion 26. Lasst uns unsere Umwelt bewahren!",
"Қоршаған ортамызды сақтайық!": "Lasst uns unsere Umwelt bewahren!",
"Қоршаған ортаны қорғайтын мамандықтарды атау, «Атамекен» әні мен «Мәңгілік алау» балетін таныту және кейіпкер, көрініс ұғымдарын түсіндіру.": "Berufe nennen, die die Umwelt schützen, das Lied «Atameken» und das Ballett «Ewige Flamme» vorstellen und die Begriffe Figur und Szene erklären.",
"«Атамекен» әні": "Das Lied «Atameken»",
"Бұл әннің сөзін Ш. Сариев, әнін Ж. Тұяқбаев жазған. Ән Отанымыздың әдемі табиғатын мадақтайды.": "Den Text dieses Liedes hat Sch. Sariew geschrieben, die Melodie Sch. Tujakbajew. Das Lied preist die schöne Natur unserer Heimat.",
"Төрт топ, төрт мамандық": "Vier Gruppen, vier Berufe",
"Сабақта оқушылар төрт топқа бөлінеді: Экологтер, Өртсөндірушілер, Балықшылар және Орманшылар. Әр топ өз мамандығы туралы таныстырылым дайындайды.": "In der Stunde werden die Schülerinnen und Schüler in vier Gruppen eingeteilt: Ökologen, Feuerwehrleute, Fischer und Förster. Jede Gruppe bereitet eine Präsentation über ihren Beruf vor.",
"Экологтер мен өртсөндірушілер": "Ökologen und Feuerwehrleute",
"Эколог қоршаған ортамен үйлесімді өмір сүруге көмектеседі. Өртсөндірушілер күні-түні қауіп пен қатерден сақтап, өрт шықса көмекке келеді.": "Ein Ökologe hilft, im Einklang mit der Umwelt zu leben. Feuerwehrleute schützen Tag und Nacht vor Gefahr und Not und kommen zu Hilfe, wenn ein Feuer ausbricht.",
"Балықшылар мен орманшылар": "Fischer und Förster",
"Балықшылар балықтың қасиетін біледі және балық өсетін су ортасының тазалығын сақтайды. Орманшылар орманды қорғап, түрлі міндеттерді атқарады.": "Fischer kennen die Eigenschaften der Fische und halten das Wasser sauber, in dem die Fische leben. Förster schützen den Wald und erfüllen verschiedene Aufgaben.",
"Бұл балеттің музыкасын С. Еркімбеков жазған. Балет — музыкалық-хореографиялық қойылым. Онда кейіпкерлер сөйлемей, би мен музыка арқылы өз ойын көрсетеді.": "Die Musik dieses Balletts hat S. Erkimbekow geschrieben. Ein Ballett ist eine Aufführung aus Musik und Tanz. Die Figuren sprechen nicht, sondern zeigen ihre Gedanken durch Tanz und Musik.",
"Кім не істейді?": "Wer macht was?",
"Әр сөйлемді қай мамандыққа жататынын тап.": "Finde heraus, zu welchem Beruf jeder Satz gehört.",
"Бұл қай мамандыққа қатысты?": "Zu welchem Beruf gehört das?",
